/**
 * Logo oficial "Lanche do Kadu" — PNG RGBA com transparência real.
 *
 * Embutida em base64 (em vez de import de arquivo binário) para que a logo
 * nunca quebre o build, independente do estado da pasta `assets/`.
 * Gerada a partir de logo.png 1254x1254 -> redimensionada para 512x512.
 */

const LOGO_BASE64 =
  "data:image/png;base64,";

export const LOGO_DATA_URI = LOGO_BASE64;
export const LOGO_HAS_ALPHA = true;
